import "./style.css";
import "./typography.css";
import "./legibility.css";
import "./motion.css";
export * from "./icons";
export * from "./core";
export * from "./controls";
export * from "./feedback";
export * from "./illustrations";

"use client";
import {
  forwardRef,
  useEffect,
  useRef,
  type CSSProperties,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type ReactNode,
} from "react";
import { Icon, type IconName } from "./icons";
import { useReducedMotion } from "./motion-preference";
import {
  GameIllustration,
  illustrations,
  type IllustrationName,
} from "./illustrations";
export type Tone = "blue" | "gold" | "green" | "red" | "purple" | "stone";
const artworkByIcon: Partial<Record<IconName, IllustrationName>> = {
  sword: "knight",
  leaf: "ranger",
  flame: "fireball",
  shield: "guardian",
  coin: "coin",
  gem: "gem",
  bolt: "elixir",
};
export function DisplayTitle({
  children,
  as: Tag = "h2",
  tone = "gold",
  size = "md",
  arched = false,
  className,
}: {
  children: string;
  as?: "h1" | "h2" | "h3";
  tone?: "gold" | "ivory" | "blue";
  size?: "sm" | "md" | "lg";
  arched?: boolean;
  className?: string;
}) {
  const letters = Array.from(children);
  return (
    <Tag
      aria-label={children}
      className={cx(
        "cr-display-title",
        `cr-title-${tone}`,
        `cr-title-${size}`,
        className,
      )}
    >
      {letters.map((letter, i) => {
        const offset = i - (letters.length - 1) / 2;
        return (
          <span
            aria-hidden="true"
            className="cr-display-glyph"
            data-letter={letter}
            style={
              arched
                ? {
                    transform: `translateY(${Math.abs(offset) * 3}px) rotate(${offset * 2}deg)`,
                  }
                : undefined
            }
            key={i}
          >
            {letter === " " ? "\u00a0" : letter}
          </span>
        );
      })}
    </Tag>
  );
}
export const cx = (...values: (string | false | undefined)[]) =>
  values.filter(Boolean).join(" ");
export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  tone?: Tone;
  size?: "sm" | "md" | "lg";
  icon?: IconName;
  loading?: boolean;
}
export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  function Button(
    {
      tone = "blue",
      size = "md",
      icon,
      loading,
      className,
      children,
      disabled,
      type = "button",
      ...props
    },
    ref,
  ) {
    return (
      <button
        ref={ref}
        type={type}
        className={cx(
          "cr-button",
          `cr-tone-${tone}`,
          `cr-button-${size}`,
          className,
        )}
        disabled={disabled || loading}
        aria-busy={loading || undefined}
        {...props}
      >
        {loading ? (
          <span className="cr-spinner" />
        ) : (
          icon && <Icon name={icon} />
        )}
        <span>{children}</span>
      </button>
    );
  },
);
export interface IconButtonProps extends Omit<
  ButtonProps,
  "children" | "icon"
> {
  icon: IconName;
  label: string;
  variant?: "standard" | "game";
}
export const IconButton = forwardRef<HTMLButtonElement, IconButtonProps>(
  function IconButton(
    { icon, label, variant = "standard", className, ...props },
    ref,
  ) {
    return (
      <Button
        ref={ref}
        aria-label={label}
        title={label}
        className={cx(
          "cr-icon-button",
          variant === "game" && "cr-icon-button-game",
          className,
        )}
        {...props}
      >
        {variant === "game" && (icon === "back" || icon === "settings") ? (
          <svg
            className="cr-navigation-icon"
            viewBox="0 0 32 32"
            aria-hidden="true"
            focusable="false"
          >
            {icon === "back" ? (
              <path d="M14 5 3 15a1.4 1.4 0 0 0 0 2l11 10V21h13a2 2 0 0 0 2-2v-6a2 2 0 0 0-2-2H14Z" />
            ) : (
              <path
                fillRule="evenodd"
                d="m13 2-.8 4.1-2.5 1.4-4-.9-3 5.1 3 3.1v2.9l-3 3.1 3 5.1 4-.9 2.5 1.4.8 4.1h6l.8-4.1 2.5-1.4 4 .9 3-5.1-3-3.1v-2.9l3-3.1-3-5.1-4 .9-2.5-1.4L19 2Zm3 8a6 6 0 1 0 0 12 6 6 0 0 0 0-12Z"
              />
            )}
          </svg>
        ) : (
          <Icon name={icon} />
        )}
      </Button>
    );
  },
);
export function Badge({
  tone = "blue",
  className,
  children,
  ...props
}: HTMLAttributes<HTMLSpanElement> & { tone?: Tone }) {
  return (
    <span className={cx("cr-badge", `cr-tone-${tone}`, className)} {...props}>
      {children}
    </span>
  );
}
export function Panel({
  title,
  action,
  tone = "stone",
  children,
  className,
  ...props
}: Omit<HTMLAttributes<HTMLElement>, "title"> & {
  title?: ReactNode;
  action?: ReactNode;
  tone?: Tone;
}) {
  return (
    <section
      className={cx("cr-panel", `cr-panel-${tone}`, className)}
      {...props}
    >
      {title && (
        <header className="cr-panel-header">
          <h3>{title}</h3>
          {action}
        </header>
      )}
      <div className="cr-panel-body">{children}</div>
    </section>
  );
}
export function Card({
  children,
  className,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return (
    <div className={cx("cr-card", className)} {...props}>
      {children}
    </div>
  );
}
export interface ProgressProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "children"
> {
  value: number;
  max?: number;
  tone?: Tone;
  label?: string;
  showValue?: boolean;
}
export function Progress({
  value,
  max = 100,
  tone = "green",
  label = "进度",
  showValue,
  className,
  ...props
}: ProgressProps) {
  const limit = Number.isFinite(max) && max > 0 ? max : 100;
  const current = Number.isFinite(value)
    ? Math.max(0, Math.min(limit, value))
    : 0;
  return (
    <div
      className={cx("cr-progress", `cr-tone-${tone}`, className)}
      role="progressbar"
      aria-label={label}
      aria-valuenow={current}
      aria-valuemin={0}
      aria-valuemax={limit}
      {...props}
    >
      <span
        className="cr-progress-fill"
        style={{ width: `${(current / limit) * 100}%` }}
      />
      {showValue && (
        <span className="cr-progress-text">
          {Math.round(current)} / {limit}
        </span>
      )}
    </div>
  );
}
export function ResourceCounter({
  icon = "coin",
  value,
  label,
  onAdd,
  tone = "gold",
}: {
  icon?: IconName;
  value: number;
  label: string;
  onAdd?: () => void;
  tone?: Tone;
}) {
  return (
    <div
      className={cx("cr-resource", `cr-resource-${tone}`)}
      aria-label={`${label} ${value}`}
    >
      <span className="cr-resource-icon">
        {artworkByIcon[icon] && illustrations[artworkByIcon[icon]!] ? (
          <GameIllustration name={artworkByIcon[icon]!} size={42} />
        ) : (
          <Icon name={icon} size={25} />
        )}
      </span>
      <span className="cr-resource-number" key={value}>
        {value.toLocaleString("en-US")}
      </span>
      {onAdd && (
        <button
          type="button"
          className="cr-resource-add"
          aria-label={`增加${label}`}
          onClick={onAdd}
        >
          <Icon name="plus" size={14} />
        </button>
      )}
    </div>
  );
}
export function Avatar({
  name,
  level,
  className,
  ...props
}: HTMLAttributes<HTMLDivElement> & { name: string; level?: number }) {
  return (
    <div
      className={cx("cr-avatar", className)}
      role="img"
      aria-label={`${name}${level ? `，等级 ${level}` : ""}`}
      {...props}
    >
      <Icon name="crown" size={30} />
      {level && <span>{level}</span>}
    </div>
  );
}
export function Divider({ children }: { children?: ReactNode }) {
  return (
    <div className="cr-divider">{children && <span>{children}</span>}</div>
  );
}
export function StarRating({
  value,
  max = 3,
  animated = false,
  size,
}: {
  value: number;
  max?: number;
  animated?: boolean;
  size?: number;
}) {
  return (
    <div
      className={cx("cr-stars", animated && "cr-stars-animated")}
      role="img"
      aria-label={`${max} 星中获得 ${value} 星`}
      style={
        size ? ({ "--cr-star-size": `${size}px` } as CSSProperties) : undefined
      }
    >
      {Array.from({ length: max }, (_, i) => (
        <span
          className={cx("cr-star-slot", i < value && "cr-star-filled")}
          style={{ "--cr-star-delay": `${i * 450 + 350}ms` } as CSSProperties}
          key={i}
        >
          <span className="cr-star-socket">
            {illustrations["star-empty"] ? (
              <GameIllustration name="star-empty" size={60} />
            ) : (
              <Icon name="star" size={48} />
            )}
          </span>
          {i < value && (
            <>
              <span className="cr-star-fill">
                {illustrations["star-filled"] ? (
                  <GameIllustration name="star-filled" size={60} />
                ) : (
                  <Icon name="star" size={48} />
                )}
              </span>
              <span className="cr-star-impact-ring" />
              <span className="cr-star-impact-flash" />
              {Array.from({ length: 6 }, (_, j) => (
                <i
                  className="cr-star-spark"
                  style={
                    {
                      "--cr-spark-x": `${Math.cos((j * Math.PI) / 3) * 70}px`,
                      "--cr-spark-y": `${Math.sin((j * Math.PI) / 3) * 55}px`,
                    } as CSSProperties
                  }
                  key={j}
                />
              ))}
            </>
          )}
        </span>
      ))}
    </div>
  );
}
export type ChestState = "idle" | "opening" | "opened";
export function Chest({
  open = false,
  size = 160,
  rarity = "rare",
  state,
  onOpenComplete,
  loop = false,
  duration = 2200,
  className = "",
}: {
  open?: boolean;
  size?: number;
  rarity?: "common" | "rare" | "epic" | "legendary";
  state?: ChestState;
  onOpenComplete?: () => void;
  loop?: boolean;
  duration?: number;
  className?: string;
}) {
  const active = state ?? (open ? "opened" : "idle");
  const reduce = useReducedMotion();
  const closedName = `chest-${rarity}` as IllustrationName;
  const openName = `chest-${rarity}-open` as IllustrationName;
  const speed = Number.isFinite(duration) ? Math.max(900, duration) : 2200;
  const completeRef = useRef(onOpenComplete);
  completeRef.current = onOpenComplete;
  useEffect(() => {
    if (active !== "opening" || !completeRef.current) return;
    const delay = reduce ? 20 : speed;
    const timer =
      loop && !reduce
        ? setInterval(() => completeRef.current?.(), delay)
        : setTimeout(() => completeRef.current?.(), delay);
    return () => {
      clearTimeout(timer);
      clearInterval(timer);
    };
  }, [active, speed, loop, reduce]);
  const label = {
    common: "普通木箱",
    rare: "稀有皇家宝箱",
    epic: "史诗宝箱",
    legendary: "传说王冠宝箱",
  }[rarity];
  return (
    <span
      role="img"
      aria-label={`${label}，${{ idle: "待机", opening: "开箱中", opened: "已开启" }[active]}`}
      aria-busy={(active === "opening" && !loop) || undefined}
      data-state={active}
      className={cx(
        "cr-chest",
        "cr-chest-illustrated",
        `cr-chest-state-${active}`,
        `cr-chest-${rarity}`,
        className,
      )}
      style={
        {
          "--cr-chest-size": `${size}px`,
          "--cr-chest-duration": `${speed}ms`,
          "--cr-chest-repeat": loop ? "infinite" : "1",
          "--cr-chest-mask": `url("${illustrations[active === "opened" ? openName : closedName] ?? ""}")`,
        } as CSSProperties
      }
    >
      <span className="cr-chest-ambient" aria-hidden="true" />
      <span className="cr-chest-rays" aria-hidden="true" />
      <span className="cr-chest-keylight" aria-hidden="true" />
      <GameIllustration
        name={closedName}
        size={size}
        aria-hidden="true"
        className="cr-chest-image cr-chest-closed-image"
      />
      <GameIllustration
        name={illustrations[openName] ? openName : closedName}
        size={size}
        aria-hidden="true"
        className="cr-chest-image cr-chest-open-image"
      />
      <span className="cr-chest-sheen" aria-hidden="true" />
      <span className="cr-chest-burst" aria-hidden="true" />
      {Array.from({ length: 20 }, (_, i) => {
        const angle = (i * Math.PI * 2) / 20;
        const distance = 55 + (i % 5) * 15;
        return (
          <i
            key={i}
            aria-hidden="true"
            className="cr-chest-particle"
            style={
              {
                "--cr-particle-x": `${Math.cos(angle) * distance}px`,
                "--cr-particle-y": `${Math.sin(angle) * distance - 40}px`,
                "--cr-particle-delay": `${(i % 4) * 15}ms`,
                "--cr-particle-rotation": `${i * 31}deg`,
              } as CSSProperties
            }
          />
        );
      })}
      {Array.from({ length: 5 }, (_, i) => (
        <i
          className="cr-chest-idle-spark"
          aria-hidden="true"
          style={{
            left: `${15 + i * 17}%`,
            top: `${25 + (i % 3) * 19}%`,
            animationDelay: `${i * 0.47}s`,
          }}
          key={`s${i}`}
        />
      ))}
    </span>
  );
}
export function LevelNode({
  level,
  state = "available",
  stars = 0,
  onClick,
  label,
}: {
  level: number;
  state?: "locked" | "available" | "completed";
  stars?: number;
  onClick?: () => void;
  label?: string;
}) {
  return (
    <div className={cx("cr-level", `cr-level-${state}`)}>
      <button
        type="button"
        className="cr-level-node"
        disabled={state === "locked"}
        aria-label={
          label || `关卡 ${level}${state === "locked" ? "，未解锁" : ""}`
        }
        onClick={onClick}
      >
        {state === "locked" ? <Icon name="lock" size={24} /> : level}
      </button>
      {state === "completed" && <StarRating value={stars} />}
    </div>
  );
}
export interface GameCardProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  name: string;
  cost: number;
  icon?: IconName;
  rarity?: "common" | "rare" | "epic";
  selected?: boolean;
  level?: number;
  artwork?: IllustrationName;
}
export function GameCard({
  name,
  cost,
  icon = "sword",
  rarity = "common",
  selected,
  level = 1,
  artwork,
  className,
  ...props
}: GameCardProps) {
  const picture = artwork ?? artworkByIcon[icon];
  return (
    <button
      type="button"
      className={cx(
        "cr-game-card",
        `cr-rarity-${rarity}`,
        selected && "cr-game-card-selected",
        className,
      )}
      aria-pressed={selected}
      aria-label={`${name}，消耗 ${cost}，等级 ${level}`}
      {...props}
    >
      <span className="cr-card-cost">{cost}</span>
      <span className="cr-card-portrait">
        {picture && illustrations[picture] ? (
          <GameIllustration name={picture} size={100} />
        ) : (
          <Icon name={icon} size={43} />
        )}
        <span className="cr-card-portrait-spark" />
      </span>
      <span className="cr-card-name">{name}</span>
      <span className="cr-card-level">等级 {level}</span>
    </button>
  );
}

import { useSyncExternalStore } from "react";

const query = "(prefers-reduced-motion: reduce)";

export function isMotionReduced() {
  if (typeof window === "undefined") return false;
  const override = document.documentElement.dataset.reducedMotion;
  if (override === "true" || override === "false") return override === "true";
  return window.matchMedia(query).matches;
}

function subscribe(onChange: () => void) {
  const media = window.matchMedia(query);
  const observer = new MutationObserver(onChange);
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["data-reduced-motion"],
  });
  media.addEventListener("change", onChange);
  return () => {
    observer.disconnect();
    media.removeEventListener("change", onChange);
  };
}

export function useReducedMotion() {
  return useSyncExternalStore(subscribe, isMotionReduced, () => false);
}

"use client";
import {
  forwardRef,
  useId,
  useRef,
  type InputHTMLAttributes,
  type SelectHTMLAttributes,
  type TextareaHTMLAttributes,
  type ReactNode,
  type KeyboardEvent,
} from "react";
import { cx } from "./core";
import { Icon } from "./icons";
export const Input = forwardRef<
  HTMLInputElement,
  InputHTMLAttributes<HTMLInputElement>
>(function Input({ className, ...props }, ref) {
  return <input ref={ref} className={cx("cr-input", className)} {...props} />;
});
export const Textarea = forwardRef<
  HTMLTextAreaElement,
  TextareaHTMLAttributes<HTMLTextAreaElement>
>(function Textarea({ className, ...props }, ref) {
  return (
    <textarea
      ref={ref}
      className={cx("cr-input", "cr-textarea", className)}
      {...props}
    />
  );
});
export const Select = forwardRef<
  HTMLSelectElement,
  SelectHTMLAttributes<HTMLSelectElement>
>(function Select({ className, ...props }, ref) {
  return (
    <select
      ref={ref}
      className={cx("cr-input", "cr-select", className)}
      {...props}
    />
  );
});
export interface CheckProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, "type"> {
  label: ReactNode;
}
export const Checkbox = forwardRef<HTMLInputElement, CheckProps>(
  function Checkbox({ label, className, ...props }, ref) {
    return (
      <label className={cx("cr-check-label", className)}>
        <input ref={ref} type="checkbox" className="cr-checkbox" {...props} />
        <span className="cr-check-box">
          <Icon name="check" size={17} />
        </span>
        <span>{label}</span>
      </label>
    );
  },
);
export interface SwitchProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, "type" | "onChange"> {
  label: ReactNode;
  onCheckedChange?: (checked: boolean) => void;
}
export const Switch = forwardRef<HTMLInputElement, SwitchProps>(function Switch(
  { label, onCheckedChange, className, ...props },
  ref,
) {
  return (
    <label className={cx("cr-switch-label", className)}>
      <input
        type="checkbox"
        role="switch"
        ref={ref}
        className="cr-switch-input"
        onChange={(e) => onCheckedChange?.(e.target.checked)}
        {...props}
      />
      <span className="cr-switch-track">
        <span />
      </span>
      <span>{label}</span>
    </label>
  );
});
export const Slider = forwardRef<
  HTMLInputElement,
  InputHTMLAttributes<HTMLInputElement> & { label: string }
>(function Slider({ label, className, ...props }, ref) {
  return (
    <input
      ref={ref}
      type="range"
      aria-label={label}
      className={cx("cr-slider", className)}
      {...props}
    />
  );
});
export interface TabItem {
  value: string;
  label: ReactNode;
  content: ReactNode;
  disabled?: boolean;
}
export function Tabs({
  items,
  value,
  onValueChange,
  label = "选项卡",
}: {
  items: TabItem[];
  value: string;
  onValueChange: (value: string) => void;
  label?: string;
}) {
  const id = useId();
  const refs = useRef<(HTMLButtonElement | null)[]>([]);
  function navigate(e: KeyboardEvent, index: number) {
    const active = items
      .map((item, i) => (!item.disabled ? i : -1))
      .filter((i) => i >= 0);
    const position = active.indexOf(index);
    const next =
      e.key === "Home"
        ? active[0]
        : e.key === "End"
          ? active.at(-1)
          : e.key === "ArrowRight"
            ? active[(position + 1) % active.length]
            : e.key === "ArrowLeft"
              ? active[(position - 1 + active.length) % active.length]
              : undefined;
    if (next !== undefined) {
      e.preventDefault();
      onValueChange(items[next].value);
      refs.current[next]?.focus();
    }
  }
  return (
    <div className="cr-tabs">
      <div className="cr-tab-list" role="tablist" aria-label={label}>
        {items.map((item, i) => (
          <button
            ref={(el) => {
              refs.current[i] = el;
            }}
            type="button"
            role="tab"
            id={`${id}-tab-${item.value}`}
            aria-controls={`${id}-panel-${item.value}`}
            aria-selected={value === item.value}
            tabIndex={value === item.value ? 0 : -1}
            disabled={item.disabled}
            onKeyDown={(e) => navigate(e, i)}
            onClick={() => onValueChange(item.value)}
            key={item.value}
          >
            {item.label}
          </button>
        ))}
      </div>
      {items.map((item) => (
        <div
          role="tabpanel"
          tabIndex={0}
          hidden={value !== item.value}
          id={`${id}-panel-${item.value}`}
          aria-labelledby={`${id}-tab-${item.value}`}
          key={item.value}
        >
          {item.content}
        </div>
      ))}
    </div>
  );
}

"use client";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { Icon } from "./icons";
import { cx, IconButton, type Tone } from "./core";
export function Dialog({
  open,
  onOpenChange,
  title,
  children,
  className,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: ReactNode;
  children: ReactNode;
  className?: string;
}) {
  const ref = useRef<HTMLDialogElement>(null);
  const id = useId();
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    if (open && !element.open) element.showModal();
    else if (!open && element.open) element.close();
  }, [open]);
  return (
    <dialog
      ref={ref}
      className={cx("cr-dialog", className)}
      aria-labelledby={id}
      onCancel={(e) => {
        e.preventDefault();
        onOpenChange(false);
      }}
      onClose={() => onOpenChange(false)}
      onClick={(e) => {
        if (e.target === e.currentTarget) onOpenChange(false);
      }}
    >
      <div className="cr-dialog-inner">
        <header>
          <h2 id={id}>{title}</h2>
          <IconButton
            icon="close"
            label="关闭弹窗"
            tone="red"
            size="sm"
            onClick={() => onOpenChange(false)}
          />
        </header>
        <div className="cr-dialog-body">{children}</div>
      </div>
    </dialog>
  );
}
type ToastOptions = { message: string; tone?: Tone; duration?: number };
type ToastData = ToastOptions & { id: number };
const ToastContext = createContext<((options: ToastOptions) => void) | null>(
  null,
);
function ToastItem({
  toast,
  dismiss,
}: {
  toast: ToastData;
  dismiss: (id: number) => void;
}) {
  useEffect(() => {
    const timer = setTimeout(() => dismiss(toast.id), toast.duration ?? 3500);
    return () => clearTimeout(timer);
  }, [toast, dismiss]);
  return (
    <div className={`cr-toast cr-tone-${toast.tone ?? "green"}`}>
      <Icon name="check" />
      <span>{toast.message}</span>
      <button
        aria-label="关闭通知"
        type="button"
        onClick={() => dismiss(toast.id)}
      >
        <Icon name="close" size={16} />
      </button>
    </div>
  );
}
export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<ToastData[]>([]);
  const counter = useRef(0);
  const dismiss = useCallback(
    (id: number) =>
      setToasts((items) => items.filter((item) => item.id !== id)),
    [],
  );
  const show = useCallback(
    (options: ToastOptions) =>
      setToasts((items) => [
        ...items.slice(-3),
        { ...options, id: ++counter.current },
      ]),
    [],
  );
  const context = useMemo(() => show, [show]);
  return (
    <ToastContext.Provider value={context}>
      {children}
      <div className="cr-toast-viewport" role="status" aria-live="polite">
        {toasts.map((toast) => (
          <ToastItem key={toast.id} toast={toast} dismiss={dismiss} />
        ))}
      </div>
    </ToastContext.Provider>
  );
}
export function useToast() {
  const value = useContext(ToastContext);
  if (!value) throw new Error("useToast must be used inside ToastProvider");
  return value;
}
export function Tooltip({
  children,
  content,
}: {
  children: ReactNode;
  content: string;
}) {
  const id = useId();
  return (
    <span className="cr-tooltip" tabIndex={0} aria-describedby={id}>
      {children}
      <span role="tooltip" id={id}>
        {content}
      </span>
    </span>
  );
}

