.cr-tooltip {
  position: relative;
  display: inline-flex;
}
.cr-tooltip > [role="tooltip"] {
  position: absolute;
  z-index: 100;
  bottom: calc(100% + 10px);
  left: 50%;
  transform: translateX(-50%) translateY(3px);
  opacity: 0;
  visibility: hidden;
  white-space: nowrap;
  padding: 7px 11px;
  background: #223951;
  color: white;
  border: 1px solid #58718b;
  border-radius: 7px;
  font-size: 20px;
  transition: 0.15s;
  box-shadow: 0 3px 0 #10253b;
  pointer-events: none;
}
.cr-tooltip:hover > [role="tooltip"],
.cr-tooltip:focus-within > [role="tooltip"],
.cr-tooltip:focus > [role="tooltip"] {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%);
}
.cr-toast-viewport {
  position: fixed;
  bottom: 25px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 2000;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: calc(100vw - 30px);
  width: max-content;
  pointer-events: none;
}
.cr-toast {
  display: flex;
  align-items: center;
  gap: 10px;
  border: 2px solid var(--cr-edge);
  border-radius: 10px;
  background: linear-gradient(var(--cr-top), var(--cr-middle));
  padding: 13px 17px;
  box-shadow:
    0 4px var(--cr-shadow),
    0 8px 20px #0002;
  animation: cr-toast-in 0.25s;
  pointer-events: auto;
  font-size: 20px;
  font-weight: 800;
}
.cr-toast button {
  border: 0;
  background: none;
  cursor: pointer;
  display: flex;
  color: inherit;
  padding: 4px;
  margin-left: 8px;
}
@keyframes cr-spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes cr-value-pop {
  50% {
    transform: scale(1.15);
    color: #ffe49b;
  }
}
@keyframes cr-star-in {
  from {
    transform: translateY(25px) scale(0.1) rotate(-30deg);
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes cr-ray-glow {
  to {
    opacity: 0.4;
    transform: translateY(-4px);
  }
}
@keyframes cr-level-pulse {
  50% {
    filter: brightness(1.12);
    box-shadow:
      inset 0 3px #fff5,
      0 6px #82612c,
      0 0 0 8px #ffe78644;
  }
}
@keyframes cr-dialog-in {
  from {
    transform: translateY(22px) scale(0.9);
    opacity: 0;
  }
  to {
    transform: none;
    opacity: 1;
  }
}
@keyframes cr-toast-in {
  from {
    transform: translateY(20px);
    opacity: 0;
  }
  to {
    transform: none;
    opacity: 1;
  }
}
@media (prefers-reduced-motion: reduce) {
  :root:not([data-reduced-motion="false"]) [class^="cr-"],
  :root:not([data-reduced-motion="false"]) [class*="\ cr-"],
  :root:not([data-reduced-motion="false"]) [class^="cr-"]::before,
  :root:not([data-reduced-motion="false"]) [class^="cr-"]::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
[data-reduced-motion="true"] [class^="cr-"],
[data-reduced-motion="true"] [class*="\ cr-"] {
  animation-duration: 0.01ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: 0.01ms !important;
}

/* Included in the built style.css. Display font files load through the optional fonts entry. */
:root,
.crown-theme {
  --cr-font: "Nunito", "Noto Sans SC", "Microsoft YaHei", sans-serif;
  --cr-font-display:
    "Crown Display Latin", "Crown Display CJK", "Noto Sans SC", sans-serif;
}
.cr-button,
.cr-game-card .cr-card-name,
.cr-panel-header h3,
.cr-dialog h2,
.cr-level-node {
  font-family: var(--cr-font-display);
  font-weight: 400;
  letter-spacing: 0.025em;
  font-synthesis: none;
}
.cr-resource-number,
.cr-card-cost,
.cr-progress-text {
  font-family: "Crown Display Latin", "Nunito", sans-serif;
  font-weight: 400;
  font-variant-numeric: tabular-nums;
}
.cr-display-title {
  --cr-title-front: #ffdb69;
  --cr-title-light: #fff7c7;
  --cr-title-low: #eeb43f;
  --cr-title-outline: #654321;
  --cr-title-depth: #a46c24;
  display: flex;
  align-items: center;
  justify-content: center;
  isolation: isolate;
  gap: 0.005em;
  font-family: var(--cr-font-display);
  font-weight: 400 !important;
  font-synthesis: none;
  line-height: 1.22;
  letter-spacing: 0.005em;
  margin: 0;
  color: var(--cr-title-front);
  padding: 0.1em 0.12em 0.16em;
}
.cr-title-ivory {
  --cr-title-front: #fff5d3;
  --cr-title-light: #fffef1;
  --cr-title-low: #f4dda3;
  --cr-title-outline: #244767;
  --cr-title-depth: #37688b;
}
.cr-title-blue {
  --cr-title-front: #8adeff;
  --cr-title-light: #e9fcff;
  --cr-title-low: #49a9ec;
  --cr-title-outline: #173f69;
  --cr-title-depth: #246da3;
}
.cr-title-sm {
  font-size: 32px;
}
.cr-title-md {
  font-size: 49px;
}
.cr-title-lg {
  font-size: 61px;
}
.cr-display-glyph {
  display: inline-block;
  position: relative;
  z-index: 0;
  color: var(--cr-title-outline);
  -webkit-text-stroke: 0.08em var(--cr-title-outline);
  paint-order: stroke fill;
  text-shadow:
    0 0.025em 0 var(--cr-title-depth),
    0 0.05em 0 var(--cr-title-depth),
    0 0.075em 0 var(--cr-title-depth),
    0 0.1em 0 var(--cr-title-outline),
    0 0.14em 0.07em #10233877;
}
.cr-display-glyph:after {
  content: attr(data-letter);
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    var(--cr-title-light) 10%,
    var(--cr-title-front) 53%,
    var(--cr-title-low) 54%,
    var(--cr-title-front) 90%
  );
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  -webkit-text-stroke: 0;
  text-shadow: none;
  filter: drop-shadow(0 -0.015em 0 var(--cr-title-light));
}

/* Readability contract: visible component text is at least 20px. */
.cr-illustration {
  display: inline-block;
  width: var(--cr-art-size, 80px);
  height: var(--cr-art-size, 80px);
  object-fit: contain;
  vertical-align: middle;
  flex-shrink: 0;
  user-select: none;
  filter: drop-shadow(0 4px 3px #132b4522);
}
.cr-chest-illustrated {
  display: inline-flex;
  position: relative;
  align-items: center;
  justify-content: center;
  width: var(--cr-chest-size, 160px);
  height: var(--cr-chest-size, 160px);
  vertical-align: middle;
  isolation: isolate;
  overflow: visible;
}
.cr-chest-illustrated > .cr-chest-image {
  position: relative;
  width: 100%;
  height: 100%;
  object-fit: contain;
  z-index: 1;
}
.cr-chest-glow {
  position: absolute;
  inset: -20%;
  background: radial-gradient(ellipse, #ffe99466, transparent 65%);
  border-radius: 50%;
  z-index: 0;
  animation: cr-ray-glow 1.7s ease-in-out infinite alternate;
  pointer-events: none;
}
.cr-chest-open > .cr-chest-image {
  animation: cr-chest-reveal 0.5s cubic-bezier(0.2, 1.2, 0.3, 1) both;
}
.cr-card-portrait .cr-illustration {
  width: 115%;
  height: 125%;
  max-width: none;
  object-fit: contain;
  transform: translateY(6%);
  filter: drop-shadow(0 4px 2px #132c4e55);
}
.cr-resource-icon:has(> .cr-illustration) {
  border: 0;
  background: none;
  box-shadow: none;
  overflow: visible;
  transform: none;
}
.cr-resource-icon > .cr-illustration {
  width: 132%;
  height: 132%;
  max-width: none;
  filter: drop-shadow(0 2px 1px #1a2b3e55);
}
@keyframes cr-chest-reveal {
  from {
    transform: scale(0.78) translateY(9px);
    opacity: 0.45;
  }
  to {
    transform: scale(1) translateY(0);
    opacity: 1;
  }
}
