/* Filled navigation glyphs stay readable over bright landscapes. */
.cr-button.cr-icon-button-game {
  width: 58px;
  height: 56px;
  min-height: 56px;
  padding: 7px;
  flex-shrink: 0;
  border: 2px solid #102c48;
  border-radius: 13px;
  background: linear-gradient(
    #88e1ff 0%,
    #39b6f3 15%,
    #1686cf 51%,
    #0963aa 52%,
    #147ec4 100%
  );
  box-shadow:
    inset 0 3px #c4f5ffb3,
    inset 0 -3px #06518b,
    0 5px #0a2b48,
    0 7px 2px #0c1c3455;
}
.cr-icon-button-game .cr-navigation-icon {
  display: block;
  width: 34px;
  height: 34px;
  overflow: visible;
  fill: #fff8de;
  stroke: #163b5b;
  stroke-width: 1.8px;
  stroke-linejoin: round;
  paint-order: stroke fill;
  filter: drop-shadow(0 3px #0b2b47);
  transform: none;
}
.cr-button.cr-icon-button-game:hover:not(:disabled) {
  filter: brightness(1.12);
}
.cr-button.cr-icon-button-game:active:not(:disabled) {
  transform: translateY(4px);
  box-shadow:
    inset 0 2px #b8ecff99,
    inset 0 -2px #06518b,
    0 1px #0a2b48;
}

/* Chest: anticipation -> golden burst -> open reveal. */
.cr-chest-illustrated {
  perspective: 700px;
  transform-origin: 50% 85%;
  overflow: visible;
}
.cr-chest-illustrated > .cr-chest-image {
  position: absolute;
  inset: 0;
  z-index: 3;
  width: 100%;
  height: 100%;
  object-fit: contain;
  transform-origin: 50% 80%;
  animation: none;
}
.cr-chest-closed-image {
  opacity: 1;
}
.cr-chest-open-image {
  opacity: 0;
}
.cr-chest-ambient,
.cr-chest-rays,
.cr-chest-keylight,
.cr-chest-burst,
.cr-chest-sheen,
.cr-chest-particle,
.cr-chest-idle-spark {
  position: absolute;
  pointer-events: none;
  display: block;
}
.cr-chest-ambient {
  inset: -15%;
  z-index: 0;
  border-radius: 50%;
  background: radial-gradient(ellipse, #ffd55b55, transparent 68%);
  opacity: 0;
}
.cr-chest-rays {
  animation: none;
  left: -70%;
  top: -67%;
  width: 240%;
  height: 240%;
  z-index: 1;
  opacity: 0;
  background: repeating-conic-gradient(
    from 3deg,
    #ffe988bb 0deg 7deg,
    transparent 7deg 25deg
  );
  mask-image: radial-gradient(ellipse, #000 8%, #0009 25%, transparent 65%);
  -webkit-mask-image: radial-gradient(
    ellipse,
    #000 8%,
    #0009 25%,
    transparent 65%
  );
  transform-origin: 50% 50%;
}
.cr-chest-keylight {
  left: 35%;
  top: -55%;
  width: 30%;
  height: 135%;
  z-index: 2;
  background: linear-gradient(transparent, #fff5bcaa 50%, #ffe565);
  clip-path: polygon(0 0, 100% 0, 62% 100%, 38% 100%);
  filter: blur(4px);
  opacity: 0;
  transform-origin: 50% 100%;
}
.cr-chest-burst {
  inset: -28%;
  border-radius: 50%;
  z-index: 5;
  background: radial-gradient(
    ellipse,
    #fffef5 0%,
    #fff9c5dd 12%,
    #ffe86c88 30%,
    transparent 65%
  );
  opacity: 0;
  mix-blend-mode: screen;
}
.cr-chest-sheen {
  inset: 0;
  z-index: 4;
  background: linear-gradient(
    115deg,
    transparent 35%,
    #fffdeb88 48%,
    transparent 61%
  );
  background-size: 350% 100%;
  mask-image: var(--cr-chest-mask);
  -webkit-mask-image: var(--cr-chest-mask);
  mask-size: contain;
  -webkit-mask-size: contain;
  mask-position: center;
  -webkit-mask-position: center;
  mask-mode: alpha;
  mask-repeat: no-repeat;
  -webkit-mask-repeat: no-repeat;
  opacity: 0.65;
}
.cr-chest-particle {
  left: 50%;
  top: 48%;
  z-index: 6;
  width: 7px;
  height: 12px;
  border-radius: 2px;
  background: linear-gradient(#fffde5, #ffd048);
  box-shadow: 0 0 10px #ffe977;
  opacity: 0;
  transform: translate(-50%, -50%);
}
.cr-chest-particle:nth-of-type(3n) {
  width: 12px;
  height: 12px;
  clip-path: polygon(
    50% 0,
    62% 36%,
    100% 50%,
    62% 64%,
    50% 100%,
    38% 64%,
    0 50%,
    38% 36%
  );
}
.cr-chest-idle-spark {
  z-index: 5;
  width: 13px;
  height: 13px;
  background: #fff9ce;
  clip-path: polygon(
    50% 0,
    62% 35%,
    100% 50%,
    62% 65%,
    50% 100%,
    38% 65%,
    0 50%,
    38% 35%
  );
  opacity: 0;
  filter: drop-shadow(0 0 5px #ffe983);
}
.cr-chest-state-idle > .cr-chest-closed-image {
  animation: cr-chest-idle-breathe 2.8s ease-in-out infinite;
}
.cr-chest-state-idle > .cr-chest-sheen {
  transform-origin: 50% 80%;
  animation:
    cr-chest-metal-glint 4.8s ease-in-out infinite,
    cr-chest-idle-breathe 2.8s ease-in-out infinite;
}
.cr-chest-state-idle > .cr-chest-idle-spark {
  animation: cr-chest-twinkle 3.2s ease-in-out infinite;
}
.cr-chest-state-opening {
  animation: cr-chest-anticipate var(--cr-chest-duration, 2200ms) ease-in-out
    var(--cr-chest-repeat, 1) both;
}
.cr-chest-state-opening > .cr-chest-closed-image {
  animation: cr-chest-close-hide var(--cr-chest-duration, 2200ms) linear
    var(--cr-chest-repeat, 1) both;
}
.cr-chest-state-opening > .cr-chest-open-image {
  animation: cr-chest-open-reveal var(--cr-chest-duration, 2200ms)
    cubic-bezier(0.2, 0.85, 0.25, 1) var(--cr-chest-repeat, 1) both;
}
.cr-chest-state-opening > .cr-chest-rays {
  animation: cr-chest-ray-burst var(--cr-chest-duration, 2200ms) ease-out
    var(--cr-chest-repeat, 1) both;
}
.cr-chest-state-opening > .cr-chest-keylight {
  animation: cr-chest-keylight-burst var(--cr-chest-duration, 2200ms)
