/* Three sockets remain underneath. Gold stars slam, squash, stretch and settle. */
.cr-stars {
  --cr-star-size: 48px;
  gap: 10px;
  isolation: isolate;
  overflow: visible;
}
.cr-stars > .cr-star-slot {
  display: block;
  position: relative;
  width: var(--cr-star-size);
  height: var(--cr-star-size);
  flex-shrink: 0;
  transform: none;
  filter: none;
  animation: none;
}
.cr-star-socket,
.cr-star-fill {
  position: absolute;
  inset: 0;
  display: block;
  transform-origin: 50% 65%;
}
.cr-star-socket {
  z-index: 0;
  filter: drop-shadow(0 2px 1px #0b182a66);
}
.cr-star-socket > .cr-illustration,
.cr-star-fill > .cr-illustration {
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter: none;
}
.cr-star-socket > svg,
.cr-star-fill > svg {
  width: 100%;
  height: 100%;
  stroke-width: 1.5;
}
.cr-star-socket > svg {
  fill: #273b53 !important;
  color: #7c91a3;
}
.cr-star-fill > svg {
  fill: #ffda5d !important;
  color: #a56c22;
}
.cr-star-fill {
  z-index: 3;
  filter: drop-shadow(0 3px 0 #8f5d2288);
}
.cr-star-fill > .cr-illustration {
  width: 94%;
  height: 94%;
  margin: 3%;
}
.cr-stars > .cr-star-slot:nth-child(2) {
  transform: none;
}
.cr-stars-animated:has(.cr-star-fill) {
  animation: cr-star-row-kick 2200ms linear both;
}
@keyframes cr-star-row-kick {
  0%,
  28%,
  34%,
  49%,
  55%,
  69%,
  76%,
  100% {
    transform: translateY(0);
  }
  30%,
  51%,
  71% {
    transform: translateY(3px);
  }
  32%,
  53%,
  73% {
    transform: translateY(-1px);
  }
}
.cr-star-impact-ring,
.cr-star-impact-flash,
.cr-star-spark {
  position: absolute;
  pointer-events: none;
  opacity: 0;
}
.cr-star-impact-ring {
  inset: 3%;
  border: 3px solid #fff1ad;
  border-radius: 50%;
  z-index: 2;
  box-shadow: 0 0 10px #ffe875;
}
.cr-star-impact-flash {
  inset: -30%;
  z-index: 2;
  background: radial-gradient(#fff9cfdd, #ffd95077 25%, transparent 63%);
  border-radius: 50%;
}
.cr-star-spark {
  left: 50%;
  top: 55%;
  width: 7px;
  height: 10px;
  background: #ffe895;
  box-shadow: 0 0 7px #ffda62;
  z-index: 4;
  border-radius: 1px;
}
.cr-stars-animated > .cr-star-slot > .cr-star-fill {
  animation: cr-star-slam var(--cr-star-duration, 760ms)
    var(--cr-star-delay, 350ms) linear both;
}
.cr-stars-animated > .cr-star-filled > .cr-star-socket {
  animation: cr-star-socket-impact var(--cr-star-duration, 760ms)
    var(--cr-star-delay, 350ms) linear both;
}
.cr-stars-animated > .cr-star-slot > .cr-star-impact-ring {
  animation: cr-star-ring var(--cr-star-duration, 760ms)
    var(--cr-star-delay, 350ms) ease-out both;
}
.cr-stars-animated > .cr-star-slot > .cr-star-impact-flash {
  animation: cr-star-flash var(--cr-star-duration, 760ms)
    var(--cr-star-delay, 350ms) ease-out both;
}
.cr-stars-animated > .cr-star-slot > .cr-star-spark {
  animation: cr-star-debris var(--cr-star-duration, 760ms)
    var(--cr-star-delay, 350ms) ease-out both;
}
@keyframes cr-star-slam {
  0% {
    opacity: 0;
    transform: translateY(-120px) scale(2.7, 2.4) rotate(-18deg);
  }
  22% {
    opacity: 1;
    transform: translateY(-52px) scale(1.65, 1.75) rotate(-9deg);
  }
  40% {
    opacity: 1;
    transform: translateY(6px) scale(1.25, 0.65) rotate(3deg);
  }
  53% {
    transform: translateY(-13px) scale(0.85, 1.18) rotate(-3deg);
  }
  68% {
    transform: translateY(4px) scale(1.1, 0.9) rotate(1deg);
  }
  82% {
    transform: translateY(-3px) scale(0.97, 1.05);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1) rotate(0);
  }
}
@keyframes cr-star-socket-impact {
  0%,
  37% {
    transform: translateY(0);
  }
  42% {
    transform: translateY(4px) scale(1.04, 0.95);
  }
  47% {
    transform: translateY(-2px);
  }
  55% {
    transform: translateY(1px);
  }
  70%,
  100% {
    transform: translateY(0);
  }
}
@keyframes cr-star-ring {
  0%,
  37% {
    opacity: 0;
    transform: scale(0.35);
  }
  42% {
    opacity: 1;
    transform: scale(0.7);
  }
  68% {
    opacity: 0;
    transform: scale(1.9);
  }
  100% {
    opacity: 0;
    transform: scale(2);
  }
}
@keyframes cr-star-flash {
  0%,
  37% {
    opacity: 0;
    transform: scale(0.25);
  }
  41% {
    opacity: 1;
    transform: scale(1);
  }
  59%,
  100% {
    opacity: 0;
    transform: scale(1.5);
  }
}
@keyframes cr-star-debris {
  0%,
  38% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.1);
  }
  44% {
    opacity: 1;
    transform: translate(
        calc(-50% + var(--cr-spark-x) * 0.2),
        calc(-50% + var(--cr-spark-y) * 0.2)
      )
      scale(1);
  }
  75% {
    opacity: 0;
    transform: translate(
        calc(-50% + var(--cr-spark-x)),
        calc(-50% + var(--cr-spark-y))
      )
      rotate(150deg) scale(0.25);
  }
  100% {
    opacity: 0;
  }
}
.cr-level .cr-stars {
  --cr-star-size: 22px;
  gap: 0;
}
.cr-stars:not(.cr-stars-animated) .cr-star-fill {
  opacity: 1;
  transform: none;
}
@media (prefers-reduced-motion: reduce) {
  :root:not([data-reduced-motion="false"]) .cr-star-fill {
    opacity: 1 !important;
    transform: none !important;
  }
  :root:not([data-reduced-motion="false"]) .cr-chest-state-opening > .cr-chest-open-image {
    opacity: 1 !important;
    transform: none !important;
  }
  :root:not([data-reduced-motion="false"]) .cr-chest-state-opening > .cr-chest-closed-image {
    opacity: 0 !important;
  }
}
[data-reduced-motion="true"] .cr-star-fill {
  opacity: 1 !important;
  transform: none !important;
}
[data-reduced-motion="true"] .cr-chest-state-opening > .cr-chest-open-image {
  opacity: 1 !important;
  transform: none !important;
}
[data-reduced-motion="true"] .cr-chest-state-opening > .cr-chest-closed-image {
  opacity: 0 !important;
}

"use client";
import type { CSSProperties, ImgHTMLAttributes } from "react";
import { illustrations, type IllustrationName } from "./art";
export { illustrations, type IllustrationName } from "./art";
export interface GameIllustrationProps
  extends Omit<
    ImgHTMLAttributes<HTMLImageElement>,
    "src" | "width" | "height"
  > {
  name: IllustrationName;
  size?: number;
}
export function GameIllustration({
  name,
  size = 80,
  alt = "",
  className = "",
  style,
  ...props
}: GameIllustrationProps) {
  const source = illustrations[name];
  if (!source) return null;
  return (
    <img
      src={source}
      alt={alt}
      draggable={false}
      decoding="async"
      className={`cr-illustration ${className}`}
      style={{ "--cr-art-size": `${size}px`, ...style } as CSSProperties}
      {...props}
    />
  );
}

